CREATE TABLE IF NOT EXISTS clients (id TEXT PRIMARY KEY,name TEXT NOT NULL,access_token TEXT UNIQUE NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY,client_id TEXT,name TEXT NOT NULL,item TEXT NOT NULL,quantity INTEGER NOT NULL,note TEXT,status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY,client_id TEXT,name TEXT NOT NULL,order_ref TEXT,text TEXT NOT NULL,created_at TEXT NOT NULL,read INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS replies (id TEXT PRIMARY KEY,message_id TEXT NOT NULL,text TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY,name TEXT NOT NULL,price TEXT NOT NULL,stock INTEGER NOT NULL DEFAULT 0,image TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS members (id TEXT PRIMARY KEY,name TEXT NOT NULL,role TEXT,image TEXT,created_at TEXT NOT NULL);
